@@ -1,47 +1,96 @@
-/** A promise queue that runs at most `concurrency` tasks at once. */
+/** A promise queue that runs at most `concurrency` tasks at once and emits lifecycle events. */

 export type Task<T> = () => Promise<T>;

 interface Waiter {
   run: () => void;
 }

+/** Events a Queue emits, with the arguments each listener receives. */
+export interface QueueEventMap {
+  /** A task was added; the argument is the new pending count. */
+  add: [pending: number];
+  /** A task finished (resolved or rejected); the argument is the new pending count. */
+  done: [pending: number];
+  /** The pending count reached zero. */
+  drain: [];
+}
+
+export type QueueEvent = keyof QueueEventMap;
+export type QueueListener<E extends QueueEvent> = (...args: QueueEventMap[E]) => void;
+
+export interface QueueOptions {
+  concurrency?: number;
+  /** Receives one line each time the queue drains. */
+  logger?: (msg: string) => void;
+}
+
 export class Queue {
   private running = 0;
   private readonly waiting: Waiter[] = [];
+  private readonly concurrency: number;
+  private readonly listeners = new Map<QueueEvent, Array<(...args: never[]) => void>>();

-  constructor(private readonly concurrency = 4) {
-    if (concurrency < 1) {
+  constructor(options: number | QueueOptions = {}) {
+    const opts = typeof options === "number" ? { concurrency: options } : options;
+    this.concurrency = opts.concurrency ?? 4;
+    if (this.concurrency < 1) {
       throw new RangeError("concurrency must be at least 1");
     }
+    const logger = opts.logger ?? console.log;
+    this.on("drain", () => logger("queue drained"));
   }

   /** Number of tasks that have been added and not yet finished. */
   get pending(): number {
     return this.running + this.waiting.length;
   }

+  /** Subscribe to an event. Returns a function that unsubscribes. */
+  on<E extends QueueEvent>(event: E, listener: QueueListener<E>): () => void {
+    const list = this.listeners.get(event) ?? [];
+    list.push(listener as (...args: never[]) => void);
+    this.listeners.set(event, list);
+    return () => {
+      const i = list.indexOf(listener as (...args: never[]) => void);
+      if (i >= 0) {
+        list.splice(i, 1);
+      }
+    };
+  }
+
   add<T>(task: Task<T>): Promise<T> {
     return new Promise<T>((resolve, reject) => {
       const run = () => {
         this.running++;
         task().then(resolve, reject).finally(() => {
           this.running--;
+          this.emit("done", this.pending);
+          if (this.pending === 0) {
+            this.emit("drain");
+          }
           this.next();
         });
       };
       if (this.running < this.concurrency) {
         run();
       } else {
         this.waiting.push({ run });
       }
+      this.emit("add", this.pending);
     });
   }

+  private emit<E extends QueueEvent>(event: E, ...args: QueueEventMap[E]): void {
+    for (const listener of this.listeners.get(event) ?? []) {
+      (listener as QueueListener<E>)(...args);
+    }
+  }
+
   private next(): void {
     const w = this.waiting.shift();
     if (w) {
       w.run();
     }
   }
 }
